import{_ as e,o as i,c as a,a3 as s}from"./chunks/framework.C6R8kWFE.js";const k=JSON.parse('{"title":"Syntax, Types & Mutability","description":"","frontmatter":{},"headers":[],"relativePath":"guide/syntax-and-types.md","filePath":"guide/syntax-and-types.md"}'),l={name:"guide/syntax-and-types.md"};function n(o,t,d,c,r,p){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="syntax-types-mutability" tabindex="-1">Syntax, Types &amp; Mutability <a class="header-anchor" href="#syntax-types-mutability" aria-label="Permalink to &quot;Syntax, Types &amp; Mutability&quot;">​</a></h1><p>GlueIR is a statically and strongly typed language with an emphasis on explicit variable mutability and clear syntax.</p><hr><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2><p>GlueIR supports both single-line comments and distinctive block comments:</p><ul><li><strong>Single-line comment</strong>: Begins with <code>//</code> and continues to the end of the line.</li><li><strong>GlueIR block comment</strong>: Begins with <code>/*g</code> and ends with <code>g*/</code>.</li></ul><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// This is a standard single-line comment</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/*g</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  This is a GlueIR block comment.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  It can span multiple lines.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">g*/</span></span></code></pre></div><hr><h2 id="data-types" tabindex="-1">Data Types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data Types&quot;">​</a></h2><p>GlueIR provides fundamental primitive types mapped directly to native LLVM representations:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">LLVM Equivalent</th><th style="text-align:left;">Description</th><th style="text-align:left;">Example Literal</th></tr></thead><tbody><tr><td style="text-align:left;"><code>int</code></td><td style="text-align:left;"><code>i32</code></td><td style="text-align:left;">32-bit signed integer</td><td style="text-align:left;"><code>42</code>, <code>-10</code></td></tr><tr><td style="text-align:left;"><code>float</code></td><td style="text-align:left;"><code>float</code></td><td style="text-align:left;">32-bit single-precision floating point</td><td style="text-align:left;"><code>3.14f</code>, <code>0.5f</code></td></tr><tr><td style="text-align:left;"><code>double</code></td><td style="text-align:left;"><code>double</code></td><td style="text-align:left;">64-bit double-precision floating point</td><td style="text-align:left;"><code>3.1415926535</code></td></tr><tr><td style="text-align:left;"><code>bool</code> / <code>boolean</code></td><td style="text-align:left;"><code>i1</code></td><td style="text-align:left;">Boolean logical values</td><td style="text-align:left;"><code>true</code>, <code>false</code></td></tr><tr><td style="text-align:left;"><code>string</code></td><td style="text-align:left;"><code>ptr</code></td><td style="text-align:left;">Null-terminated string literal</td><td style="text-align:left;"><code>&quot;Hello, Glue!&quot;</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Numeric Literals</p><p>Floating-point numbers with a trailing <code>f</code> (e.g. <code>10.5f</code>) are parsed as <code>float</code>. Floating-point numbers without suffix (e.g. <code>10.5</code>) default to <code>double</code>.</p></div><hr><h2 id="variable-declarations-mutability-modifiers" tabindex="-1">Variable Declarations &amp; Mutability Modifiers <a class="header-anchor" href="#variable-declarations-mutability-modifiers" aria-label="Permalink to &quot;Variable Declarations &amp; Mutability Modifiers&quot;">​</a></h2><p>GlueIR introduces three tiers of variable mutability:</p><h3 id="_1-standard-mutable-variables" tabindex="-1">1. Standard-Mutable Variables <a class="header-anchor" href="#_1-standard-mutable-variables" aria-label="Permalink to &quot;1. Standard-Mutable Variables&quot;">​</a></h3><p>Declared with <code>&lt;type&gt; &lt;identifier&gt; = &lt;expression&gt;;</code>. Can be reassigned arbitrarily many times.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> counter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">counter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">counter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h3 id="_2-constants-const" tabindex="-1">2. Constants (<code>const</code>) <a class="header-anchor" href="#_2-constants-const" aria-label="Permalink to &quot;2. Constants (\`const\`)&quot;">​</a></h3><p>Declared with <code>const &lt;type&gt; &lt;identifier&gt; = &lt;expression&gt;;</code>. Immutable after declaration. Any reassignment attempt causes a compile-time semantic error.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PI </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3.14159</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// PI = 3.14;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // Compile Error: cannot assign to variable &#39;PI&#39; because it is a constant</span></span></code></pre></div><h3 id="_3-sticky-variables-sticky" tabindex="-1">3. Sticky Variables (<code>sticky</code>) <a class="header-anchor" href="#_3-sticky-variables-sticky" aria-label="Permalink to &quot;3. Sticky Variables (\`sticky\`)&quot;">​</a></h3><p>Declared with <code>sticky &lt;type&gt; &lt;identifier&gt; = &lt;expression&gt;;</code>. A <code>sticky</code> variable allows <strong>exactly one</strong> reassignment during its lifetime. Any subsequent reassignment triggers a compile-time semantic error.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sticky string appStatus </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;starting&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">appStatus </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ready&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // OK: first reassignment allowed</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// appStatus = &quot;stopped&quot;;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // Compile Error: variable &#39;appStatus&#39; is &#39;sticky&#39; and has already been reassigned once</span></span></code></pre></div><hr><div class="warning custom-block"><p class="custom-block-title">Sticky Limitations</p><p>** Sticky is not allowed in while statement**</p><p>Sticky variables is not allowed in <code>while</code> statement. Declaration and asignment sticky variables in while statement results in an error.</p></div><h2 id="declaration-limitations" tabindex="-1">Declaration Limitations <a class="header-anchor" href="#declaration-limitations" aria-label="Permalink to &quot;Declaration Limitations&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Important Limitations</p><ol><li><strong>Declaration with Initialization</strong>: Variables must be initialized at declaration time (<code>int x = 5;</code>). Uninitialized declarations (<code>int x;</code>) are not supported.</li><li><strong>Compound Assignment Operators</strong>: Operators like <code>+=</code>, <code>-=</code>, <code>*=</code>, <code>/=</code>, as well as <code>++</code> and <code>--</code>, are not yet implemented. Use explicit reassignment: <code>count = count + 1;</code>.</li></ol></div>`,28)])])}const g=e(l,[["render",n]]);export{k as __pageData,g as default};
